SELECT PersonId,   CASE AlertLevel WHEN 1 THEN 'GREEN' WHEN 2 THEN 'YELLOW' WHEN 3 THEN 'ORANGE' WHEN 4 THEN 'RED' END AS DruidLevel,   n, MaxAlertDate, MaxAlertId FROM (   SELECT PersonId, AlertLevel, MAX(CreatedAt) AS MaxAlertDate, COUNT(*) AS n, MAX(AlertId) AS MaxAlertId FROM dbo.Alert   WHERE ( AlertClass LIKE 'DRUID%' ) AND ( AlertLevel > 0 )   GROUP BY PersonId, AlertLevel ) agg ORDER BY PersonId